 * 统计同一仪器下与 [from, to) 重叠的版本数量；to 为 null 表示开放区间；相邻端点不算重叠。
 */
public int countOverlap(String instrumentId, Instant from, Instant to) {
    String upperCondition = to == null
            ? "TRUE"
            : "valid_from < ?";
    var args = new java.util.ArrayList<>();
    args.add(instrumentId);
    if (to != null) {
        args.add(JdbcTimes.toDb(to));
    }
    args.add(JdbcTimes.toDb(from));
    Integer count = jdbc.queryForObject(
            "SELECT COUNT(*) FROM instrument_threshold_version "
                    + "WHERE instrument_id = ? AND " + upperCondition
                    + " AND (valid_to IS NULL OR valid_to > ?)",
            Integer.class, args.toArray());
    return count == null ? 0 : count;
}

/**
 * 统计同一仪器的开放区间版本数量。
 */
public int countOpenEnded(String instrumentId) {
    Integer count = jdbc.queryForObject(
            "SELECT COUNT(*) FROM instrument_threshold_version WHERE instrument_id = ? AND valid_to IS NULL",
            Integer.class, instrumentId);
    return count == null ? 0 : count;
}

