package com.example.starter.calibration.repo;

import java.sql.PreparedStatement;
import java.sql.Statement;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

import com.example.starter.calibration.model.Measurement;
import com.example.starter.calibration.model.MeasurementStatus;

/**
 * 测量记录持久化。measurement_key 全局唯一作为幂等键；状态流转由放行事务在行锁内完成。
 */
@Repository
public class MeasurementRepository {

    private static final RowMapper<Measurement> MAPPER = (rs, rowNum) -> new Measurement(
            rs.getLong("id"),
            rs.getString("measurement_key"),
            rs.getString("instrument_id"),
            JdbcTimes.fromDb(rs.getObject("measured_at", LocalDateTime.class)),
            rs.getBigDecimal("raw_reading"),
            rs.getBigDecimal("lower_limit"),
            rs.getBigDecimal("upper_limit"),
            rs.getString("submitted_by"),
            rs.getLong("certificate_id"),
            rs.getBigDecimal("computed_value"),
            rs.getBoolean("passed"),
            MeasurementStatus.valueOf(rs.getString("status")),
            rs.getLong("version"),
            JdbcTimes.fromDb(rs.getObject("created_at", LocalDateTime.class)));

    private final JdbcTemplate jdbc;

    public MeasurementRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 插入测量记录并返回生成的 ID；measurement_key 冲突时抛出 DuplicateKeyException。
     */
    public long insert(Measurement measurement) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO measurement "
                            + "(measurement_key, instrument_id, measured_at, raw_reading, lower_limit, upper_limit, "
                            + "submitted_by, certificate_id, computed_value, passed, status, version, created_at) "
                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, measurement.measurementKey());
            ps.setString(2, measurement.instrumentId());
            ps.setObject(3, JdbcTimes.toDb(measurement.measuredAt()));
            ps.setBigDecimal(4, measurement.rawReading());
            ps.setBigDecimal(5, measurement.lowerLimit());
            ps.setBigDecimal(6, measurement.upperLimit());
            ps.setString(7, measurement.submittedBy());
            ps.setLong(8, measurement.certificateId());
            ps.setBigDecimal(9, measurement.computedValue());
            ps.setBoolean(10, measurement.passed());
            ps.setString(11, measurement.status().name());
            ps.setLong(12, measurement.version());
            ps.setObject(13, JdbcTimes.toDb(measurement.createdAt()));
            return ps;
        }, keyHolder);
        return keyHolder.getKey().longValue();
    }

    /**
     * 按测量键查询（不加锁）。
     */
    public Optional<Measurement> findByKey(String key) {
        return jdbc.query("SELECT * FROM measurement WHERE measurement_key = ?", MAPPER, key)
                .stream().findFirst();
    }

    /**
     * 按测量键查询并加行锁（须在事务内调用），用于放行、修订与预算修改时串行化状态流转。
     */
    public Optional<Measurement> findByKeyForUpdate(String key) {
        return jdbc.query("SELECT * FROM measurement WHERE measurement_key = ? FOR UPDATE", MAPPER, key)
                .stream().findFirst();
    }

    /**
     * 将测量记录置为已放行（须在持有行锁的事务内调用）。
     */
    public void markReleased(long id) {
        jdbc.update("UPDATE measurement SET status = ? WHERE id = ?",
                MeasurementStatus.RELEASED.name(), id);
    }

    /**
     * 修订测量（须在持有行锁的事务内调用）：覆盖测量字段、重新固化计算与判定，版本号自增 1。
     * 状态（PENDING/RELEASED）与提交人保持不变。
     */
    public void applyRevision(Measurement m) {
        jdbc.update("UPDATE measurement SET measured_at = ?, raw_reading = ?, lower_limit = ?, "
                        + "upper_limit = ?, certificate_id = ?, computed_value = ?, passed = ?, version = ? "
                        + "WHERE id = ?",
                JdbcTimes.toDb(m.measuredAt()), m.rawReading(), m.lowerLimit(), m.upperLimit(),
                m.certificateId(), m.computedValue(), m.passed(), m.version(), m.id());
    }

    /**
     * 查询当前可用结果：已放行且证书未撤销。instrumentId 为 null 时不过滤仪器。
     */
    public List<Measurement> findUsable(String instrumentId) {
        String base = "SELECT m.* FROM measurement m "
                + "JOIN calibration_certificate c ON c.id = m.certificate_id "
                + "WHERE m.status = 'RELEASED' AND c.revoked = FALSE ";
        if (instrumentId == null) {
            return jdbc.query(base + "ORDER BY m.id", MAPPER);
        }
        return jdbc.query(base + "AND m.instrument_id = ? ORDER BY m.id", MAPPER, instrumentId);
    }
}

package com.example.starter.calibration;

import org.junit.jupiter.api.Test;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * 阈值版本 H2 集成测试：创建、开放区间修订衔接、区间重叠 409、阈值为负 422、404；
 * 阈值按测量时刻（左闭右开）解析，后续修订不改写已固化的旧放行快照。
 */
class ThresholdApiTest extends AbstractCalibrationApiTest {

    @Test
    void createThresholdReturns201WithVersion() throws Exception {
        createOpenThreshold("INS-T", "2026-01-01T00:00:00Z", "0.5");
        mvc.perform(get("/api/thresholds/{id}", 1L))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(1))
                .andExpect(jsonPath("$.instrumentId").value("INS-T"))
                .andExpect(jsonPath("$.maxUncertainty").value("0.5"))
                .andExpect(jsonPath("$.validTo").doesNotExist());
    }

    @Test
    void negativeThresholdIs422AndMalformedIs400() throws Exception {
        mvc.perform(post("/api/thresholds").contentType("application/json")
                        .content("""
                                {"instrumentId":"INS-T","validFrom":"2026-01-01T00:00:00Z",
                                 "maxUncertainty":"-0.01"}"""))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.code").value("INVALID_NONNEGATIVE_VALUE"));
        mvc.perform(post("/api/thresholds").contentType("application/json")
                        .content("""
                                {"instrumentId":"INS-T","validFrom":"2026-01-01T00:00:00Z",
                                 "maxUncertainty":"nope"}"""))
                .andExpect(status().isBadRequest());
    }

    @Test
    void boundedOverlapRejectedButAdjacentAllowed() throws Exception {
        createThreshold("INS-T", "2026-01-01T00:00:00Z", "2026-06-01T00:00:00Z", "1");
        // 重叠
        mvc.perform(post("/api/thresholds").contentType("application/json")
                        .content("""
                                {"instrumentId":"INS-T","validFrom":"2026-03-01T00:00:00Z",
                                 "validTo":"2026-09-01T00:00:00Z","maxUncertainty":"1"}"""))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("THRESHOLD_OVERLAP"));
        // 相邻（右开端点相接）
        createThreshold("INS-T", "2026-06-01T00:00:00Z", "2027-01-01T00:00:00Z", "1");
        // 其他仪器不受影响
        createThreshold("INS-X", "2026-01-01T00:00:00Z", "2027-01-01T00:00:00Z", "1");
        mvc.perform(get("/api/thresholds/{id}", 999999)).andExpect(status().isNotFound());
    }

    @Test
    void openEndedRevisionClosesPreviousAtNewStartAndResolvesByMeasuredInstant() throws Exception {
        // v1 开放区间 [2026-01-01, ∞) 阈值 1
        long v1 = createOpenThreshold("INS-T", "2026-01-01T00:00:00Z", "1");
        // v2 开放区间 [2027-01-01, ∞)：v1 被收敛为 [2026-01-01, 2027-01-01)
        long v2 = createOpenThreshold("INS-T", "2027-01-01T00:00:00Z", "0.2");

        mvc.perform(get("/api/thresholds/{id}", v1))
                .andExpect(jsonPath("$.version").value(1))
                .andExpect(jsonPath("$.validTo").value("2027-01-01T00:00:00Z"))
                .andExpect(jsonPath("$.maxUncertainty").value("1"));
        mvc.perform(get("/api/thresholds/{id}", v2))
                .andExpect(jsonPath("$.version").value(2))
                .andExpect(jsonPath("$.validTo").doesNotExist())
                .andExpect(jsonPath("$.maxUncertainty").value("0.2"));

        // 左闭右开解析：2026 年测量走 v1，2027 年起走 v2，恰好 2027-01-01 走 v2
        createCertificate("INS-T", "2026-01-01T00:00:00Z", "2029-01-01T00:00:00Z", "1", "0");
        submitMeasurement("M-OLD", "INS-T", "2026-12-31T23:59:59Z", "1", "0", "9", "alice");
        submitMeasurement("M-BOUND", "INS-T", "2027-01-01T00:00:00Z", "1", "0", "9", "alice");
        submitMeasurement("M-NEW", "INS-T", "2027-06-01T00:00:00Z", "1", "0", "9", "alice");
        registerBudget("M-OLD", "alice", budgetJson("u", "0.9"), null).andExpect(status().isOk());
        registerBudget("M-BOUND", "alice", budgetJson("u", "0.9"), null).andExpect(status().isOk());
        registerBudget("M-NEW", "alice", budgetJson("u", "0.1"), null).andExpect(status().isOk());

        // 0.9 ≤ v1 的 1：放行成功；恰好边界时刻走 v2(0.2)：超阈值 422；新测量 0.1 ≤ 0.2：成功
        release("carol", null, "{\"keys\":[\"M-OLD\"]}").andExpect(status().isOk());
        release("carol", null, "{\"keys\":[\"M-BOUND\"]}")
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.failures[0].reasons[0]").value("UNCERTAINTY_EXCEEDS_THRESHOLD"));
        release("carol", null, "{\"keys\":[\"M-NEW\"]}").andExpect(status().isOk());
    }

    @Test
    void newOpenEndedBeforeExistingStartRejected() throws Exception {
        createOpenThreshold("INS-T", "2027-01-01T00:00:00Z", "1");
        mvc.perform(post("/api/thresholds").contentType("application/json")
                        .content("""
                                {"instrumentId":"INS-T","validFrom":"2026-01-01T00:00:00Z",
                                 "maxUncertainty":"1"}"""))
                .andExpect(status().isConflict());
    }
}

